-- CAREEROS P3-T07: the Super Admin console (phase plan D6, D7). The CREATE TABLE, index and foreign key statements are
-- generated by drizzle-kit (the two id defaults are gen_random_uuid()::text, not careeros_uuidv7(), so the plan migration's down.sql does not depend on this one); everything else is
-- written by hand, following P3-T01 and P3-T04. Runs as the migration (owner) role. Down migration: down.sql in this
-- folder.
--
-- Every cross-organization read or write of the platform console is a SECURITY DEFINER function that
--   1. is given the acting user's id (taken from the session by the server, never from the client) and checks INSIDE
--      the function that it is a platform admin: an existing, not banned user with the Better Auth `admin` role and
--      two-factor authentication enabled (careeros_assert_platform_admin);
--   2. does its work, and
--   3. writes its audit_log row in the same transaction (action `admin.*`, ids and small JSON, no personal data
--      beyond ids and the free-text reason an admin typed).
-- Functions pin search_path = pg_catalog, public, are revoked from PUBLIC and granted to careeros_app only. The app
-- role keeps NOBYPASSRLS and no privilege on the three new tables.
--> statement-breakpoint
CREATE TABLE "announcement" (
	"id" text PRIMARY KEY DEFAULT gen_random_uuid()::text,
	"title" text NOT NULL,
	"body" text NOT NULL,
	"severity" text DEFAULT 'info' NOT NULL,
	"starts_at" timestamp with time zone NOT NULL,
	"ends_at" timestamp with time zone NOT NULL,
	"plan_id" text,
	"organization_id" text,
	"created_by" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "announcement_severity_check" CHECK ("severity" in ('info', 'warning')),
	CONSTRAINT "announcement_title_check" CHECK (char_length("title") between 1 and 120),
	CONSTRAINT "announcement_body_check" CHECK (char_length("body") between 1 and 1000),
	CONSTRAINT "announcement_window_check" CHECK ("ends_at" > "starts_at")
);
--> statement-breakpoint
CREATE TABLE "announcement_dismissal" (
	"announcement_id" text,
	"user_id" text,
	"dismissed_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "announcement_dismissal_pkey" PRIMARY KEY("announcement_id","user_id")
);
--> statement-breakpoint
CREATE TABLE "impersonation" (
	"id" text PRIMARY KEY DEFAULT gen_random_uuid()::text,
	"impersonator_user_id" text NOT NULL,
	"target_user_id" text NOT NULL,
	"organization_id" text NOT NULL,
	"reason" text NOT NULL,
	"target_origin" text NOT NULL,
	"token_hash" text NOT NULL,
	"token_expires_at" timestamp with time zone NOT NULL,
	"redeemed_at" timestamp with time zone,
	"session_id" text,
	"started_at" timestamp with time zone DEFAULT now() NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"ended_at" timestamp with time zone,
	"end_reason" text,
	CONSTRAINT "impersonation_end_reason_check" CHECK ("end_reason" in ('ended', 'expired')),
	CONSTRAINT "impersonation_ended_check" CHECK (("ended_at" is null) = ("end_reason" is null))
);
--> statement-breakpoint
CREATE INDEX "announcement_window_idx" ON "announcement" ("starts_at","ends_at");--> statement-breakpoint
CREATE INDEX "announcement_dismissal_user_idx" ON "announcement_dismissal" ("user_id");--> statement-breakpoint
CREATE INDEX "impersonation_session_idx" ON "impersonation" ("session_id");--> statement-breakpoint
CREATE INDEX "impersonation_expires_idx" ON "impersonation" ("expires_at");--> statement-breakpoint
ALTER TABLE "announcement_dismissal" ADD CONSTRAINT "announcement_dismissal_announcement_id_announcement_id_fkey" FOREIGN KEY ("announcement_id") REFERENCES "announcement"("id");--> statement-breakpoint
ALTER TABLE "announcement_dismissal" ADD CONSTRAINT "announcement_dismissal_user_id_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "user"("id") ON DELETE CASCADE;--> statement-breakpoint
-- 1. Row-level security and privileges. The three tables are global (no tenant policy on purpose): the app role has NO
-- privilege and NO policy on them, so it can neither read nor write them directly; the definer functions below are the
-- only way in. FORCE applies the policy to the owner too, so only owner_access lets the owner role (migrations, definer
-- functions) in. The REVOKE is repeated in infra/db/bootstrap-roles.sql because that script's blanket GRANT would undo
-- it. A fresh test database migrates before the role exists, so the REVOKE is conditional.
ALTER TABLE "announcement" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "announcement" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
DROP POLICY IF EXISTS "owner_access" ON "announcement";--> statement-breakpoint
CREATE POLICY "owner_access" ON "announcement" TO CURRENT_USER USING (true) WITH CHECK (true);--> statement-breakpoint
ALTER TABLE "announcement_dismissal" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "announcement_dismissal" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
DROP POLICY IF EXISTS "owner_access" ON "announcement_dismissal";--> statement-breakpoint
CREATE POLICY "owner_access" ON "announcement_dismissal" TO CURRENT_USER USING (true) WITH CHECK (true);--> statement-breakpoint
ALTER TABLE "impersonation" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "impersonation" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
DROP POLICY IF EXISTS "owner_access" ON "impersonation";--> statement-breakpoint
CREATE POLICY "owner_access" ON "impersonation" TO CURRENT_USER USING (true) WITH CHECK (true);--> statement-breakpoint
DO $$ BEGIN
	IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'careeros_app') THEN
		REVOKE ALL ON TABLE public.announcement, public.announcement_dismissal, public.impersonation FROM careeros_app;
	END IF;
END $$;--> statement-breakpoint
-- 2. The platform-admin check. Exact rules: the user exists, has the `admin` role (Better Auth stores roles as a comma
-- separated list), is not banned (a ban that has expired does not count) and has two-factor authentication enabled.
-- careeros_is_platform_admin answers true or false; careeros_assert_platform_admin raises (SQLSTATE 42501). The
-- message names the reason so the server can map it: "not a platform admin" or "two-factor authentication is required".
CREATE OR REPLACE FUNCTION public.careeros_is_platform_admin(p_user_id text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
	SELECT EXISTS (
		SELECT 1 FROM public."user" u
		WHERE u.id = p_user_id
			AND 'admin' = ANY (string_to_array(replace(coalesce(u.role, ''), ' ', ''), ','))
			AND (NOT coalesce(u.banned, false) OR (u.ban_expires IS NOT NULL AND u.ban_expires <= now()))
			AND u.two_factor_enabled
	)
$$;--> statement-breakpoint
CREATE OR REPLACE FUNCTION public.careeros_assert_platform_admin(p_actor text) RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	u public."user"%ROWTYPE;
BEGIN
	SELECT * INTO u FROM public."user" WHERE id = p_actor;
	IF NOT FOUND
		OR NOT ('admin' = ANY (string_to_array(replace(coalesce(u.role, ''), ' ', ''), ',')))
		OR (coalesce(u.banned, false) AND (u.ban_expires IS NULL OR u.ban_expires > now())) THEN
		RAISE EXCEPTION 'careeros_admin: the actor is not a platform admin' USING ERRCODE = '42501';
	END IF;
	IF NOT u.two_factor_enabled THEN
		RAISE EXCEPTION 'careeros_admin: two-factor authentication is required' USING ERRCODE = '42501';
	END IF;
END
$$;--> statement-breakpoint
-- The reason an admin types for an action that changes something: 3 to 500 characters.
CREATE OR REPLACE FUNCTION public.careeros_admin_check_reason(p_reason text) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, public AS $$
BEGIN
	IF p_reason IS NULL OR char_length(btrim(p_reason)) < 3 OR char_length(p_reason) > 500 THEN
		RAISE EXCEPTION 'careeros_admin: a reason of 3 to 500 characters is required';
	END IF;
	RETURN btrim(p_reason);
END
$$;--> statement-breakpoint
-- The quota period of an organization, the same rule as @careeros/ai-metering (period.ts): the subscription's current
-- period when it contains now, else the UTC calendar month.
CREATE OR REPLACE FUNCTION public.careeros_quota_period(
	p_start timestamptz, p_end timestamptz, OUT period_start timestamptz, OUT period_end timestamptz
) LANGUAGE sql STABLE SET search_path = pg_catalog, public AS $$
	SELECT
		CASE WHEN p_start IS NOT NULL AND p_end IS NOT NULL AND p_start < p_end AND p_start <= now() AND now() < p_end
			THEN p_start ELSE date_trunc('month', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' END,
		CASE WHEN p_start IS NOT NULL AND p_end IS NOT NULL AND p_start < p_end AND p_start <= now() AND now() < p_end
			THEN p_end ELSE (date_trunc('month', now() AT TIME ZONE 'UTC') + interval '1 month') AT TIME ZONE 'UTC' END
$$;--> statement-breakpoint
-- 3. careeros_admin_list_orgs: one page of organizations, with the numbers an admin needs and NO member names or emails.
-- Seats used = members plus pending, unexpired invitations; the limit is the effective one (subscription.seats while the
-- subscription is live with a provider, else the plan's seat_limit; null = unlimited). "Last active" is the latest
-- user.last_active_at among the members. AI credits are the platform credits of the current quota period. Search matches
-- name or slug (substring, case-insensitive) or the exact id. Writes one platform audit row, `admin.orgs_listed`, with no
-- detail.
CREATE OR REPLACE FUNCTION public.careeros_admin_list_orgs(
	p_actor text, p_search text, p_status text, p_plan text, p_limit integer, p_offset integer
) RETURNS TABLE (
	org_id text, org_name text, org_slug text, org_status text, org_plan_id text, org_plan_name text,
	seats_used integer, seat_limit integer, created_at timestamptz, last_active_at timestamptz,
	ai_credits_used bigint, total_count bigint
)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
#variable_conflict use_column
DECLARE
	lim integer := least(greatest(coalesce(p_limit, 25), 1), 100);
	skip integer := greatest(coalesce(p_offset, 0), 0);
	term text := nullif(btrim(coalesce(p_search, '')), '');
	pattern text;
BEGIN
	PERFORM public.careeros_assert_platform_admin(p_actor);
	INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, metadata)
	VALUES (NULL, p_actor, 'admin.orgs_listed', 'organization', '{}'::jsonb);
	pattern := CASE WHEN term IS NULL THEN NULL
		ELSE '%' || replace(replace(replace(term, '\', '\\'), '%', '\%'), '_', '\_') || '%' END;
	RETURN QUERY
	WITH filtered AS (
		SELECT o.* FROM public.organization o
		WHERE (term IS NULL OR o.name ILIKE pattern ESCAPE '\' OR o.slug ILIKE pattern ESCAPE '\' OR o.id = term)
			AND (p_status IS NULL OR o.status = p_status)
			AND (p_plan IS NULL OR o.plan_id = p_plan)
	), page AS (
		SELECT f.*, count(*) OVER () AS total FROM filtered f ORDER BY f.created_at DESC, f.id LIMIT lim OFFSET skip
	)
	SELECT
		pg.id, pg.name, pg.slug, pg.status, pg.plan_id, pl.name,
		((SELECT count(*) FROM public.member m WHERE m.organization_id = pg.id)
			+ (SELECT count(*) FROM public.invitation i
				WHERE i.organization_id = pg.id AND i.status = 'pending' AND i.expires_at > now()))::integer,
		CASE WHEN s.status IN ('active', 'trialing', 'past_due') AND s.provider <> 'none' THEN s.seats ELSE pl.seat_limit END,
		pg.created_at,
		(SELECT max(u.last_active_at) FROM public.member m JOIN public."user" u ON u.id = m.user_id
			WHERE m.organization_id = pg.id),
		coalesce((
			SELECT sum(a.credits) FROM public.ai_usage a
			WHERE a.organization_id = pg.id AND a.source = 'platform'
				AND a.created_at >= qp.period_start AND a.created_at < qp.period_end
		), 0)::bigint,
		pg.total
	FROM page pg
	JOIN public.plan pl ON pl.id = pg.plan_id
	LEFT JOIN public.subscription s ON s.organization_id = pg.id
	CROSS JOIN LATERAL public.careeros_quota_period(s.current_period_start, s.current_period_end) qp
	ORDER BY pg.created_at DESC, pg.id;
END
$$;--> statement-breakpoint
-- 4. careeros_admin_get_org: everything about one organization as one JSON document: the organization, plan,
-- subscription, seats, this period's AI usage (with a per-feature breakdown), the ten latest billing events and the
-- owners' names and emails (the only personal data the console shows, and only here). Writes `admin.org_viewed` for the
-- organization.
CREATE OR REPLACE FUNCTION public.careeros_admin_get_org(p_actor text, p_org_id text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	org public.organization%ROWTYPE;
	pl public.plan%ROWTYPE;
	sub public.subscription%ROWTYPE;
	qp record;
	members integer;
	pending integer;
	credits_total bigint;
BEGIN
	PERFORM public.careeros_assert_platform_admin(p_actor);
	SELECT * INTO org FROM public.organization WHERE id = p_org_id;
	IF NOT FOUND THEN
		RAISE EXCEPTION 'careeros_admin: unknown organization';
	END IF;
	INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, target_id, metadata)
	VALUES (p_org_id, p_actor, 'admin.org_viewed', 'organization', p_org_id, '{}'::jsonb);
	SELECT * INTO pl FROM public.plan WHERE id = org.plan_id;
	SELECT * INTO sub FROM public.subscription WHERE organization_id = p_org_id;
	SELECT * INTO qp FROM public.careeros_quota_period(sub.current_period_start, sub.current_period_end);
	SELECT count(*) INTO members FROM public.member WHERE organization_id = p_org_id;
	SELECT count(*) INTO pending FROM public.invitation
		WHERE organization_id = p_org_id AND status = 'pending' AND expires_at > now();
	credits_total := pl.ai_credits_per_seat::bigint * greatest(coalesce(sub.seats, 1), members);
	RETURN jsonb_build_object(
		'organization', jsonb_build_object(
			'id', org.id, 'name', org.name, 'slug', org.slug, 'status', org.status, 'planId', org.plan_id,
			'createdAt', org.created_at, 'statusChangedAt', org.status_changed_at),
		'plan', jsonb_build_object(
			'id', pl.id, 'name', pl.name, 'pricingModel', pl.pricing_model, 'seatLimit', pl.seat_limit,
			'aiCreditsPerSeat', pl.ai_credits_per_seat),
		'subscription', CASE WHEN sub.organization_id IS NULL THEN NULL ELSE jsonb_build_object(
			'provider', sub.provider, 'status', sub.status, 'seats', sub.seats, 'billingInterval', sub.billing_interval,
			'currentPeriodStart', sub.current_period_start, 'currentPeriodEnd', sub.current_period_end,
			'trialEndsAt', sub.trial_ends_at, 'graceEndsAt', sub.grace_ends_at,
			'aiOverageAllowed', sub.ai_overage_allowed) END,
		'seats', jsonb_build_object(
			'members', members, 'pendingInvitations', pending, 'used', members + pending,
			'limit', CASE WHEN sub.status IN ('active', 'trialing', 'past_due') AND sub.provider <> 'none'
				THEN sub.seats ELSE pl.seat_limit END),
		'aiUsage', jsonb_build_object(
			'periodStart', qp.period_start, 'periodEnd', qp.period_end, 'creditsTotal', credits_total,
			'credits', coalesce((SELECT sum(a.credits) FROM public.ai_usage a
				WHERE a.organization_id = p_org_id AND a.source = 'platform'
					AND a.created_at >= qp.period_start AND a.created_at < qp.period_end), 0),
			'costUsdMicros', coalesce((SELECT sum(a.cost_usd_micros) FROM public.ai_usage a
				WHERE a.organization_id = p_org_id AND a.source = 'platform'
					AND a.created_at >= qp.period_start AND a.created_at < qp.period_end), 0),
			'calls', (SELECT count(*) FROM public.ai_usage a
				WHERE a.organization_id = p_org_id AND a.created_at >= qp.period_start AND a.created_at < qp.period_end),
			'byFeature', coalesce((SELECT jsonb_agg(jsonb_build_object(
					'feature', f.feature, 'credits', f.credits, 'costUsdMicros', f.cost, 'calls', f.calls) ORDER BY f.cost DESC)
				FROM (SELECT a.feature, sum(a.credits) AS credits, sum(a.cost_usd_micros) AS cost, count(*) AS calls
					FROM public.ai_usage a
					WHERE a.organization_id = p_org_id AND a.created_at >= qp.period_start AND a.created_at < qp.period_end
					GROUP BY a.feature ORDER BY sum(a.cost_usd_micros) DESC LIMIT 20) f), '[]'::jsonb)),
		'billingEvents', coalesce((SELECT jsonb_agg(jsonb_build_object(
				'provider', e.provider, 'type', e.type, 'outcome', e.outcome, 'receivedAt', e.received_at) ORDER BY e.received_at DESC)
			FROM (SELECT * FROM public.billing_event b WHERE b.organization_id = p_org_id
				ORDER BY b.received_at DESC LIMIT 10) e), '[]'::jsonb),
		'owners', coalesce((SELECT jsonb_agg(jsonb_build_object('id', u.id, 'name', u.name, 'email', u.email) ORDER BY m.created_at)
			FROM public.member m JOIN public."user" u ON u.id = m.user_id
			WHERE m.organization_id = p_org_id AND 'owner' = ANY (string_to_array(replace(m.role, ' ', ''), ','))), '[]'::jsonb)
	);
END
$$;--> statement-breakpoint
-- 5. careeros_admin_set_org_status: suspend or reactivate. `suspended` suspends. `active` reactivates to the status the
-- organization's subscription points at (`trial` while trialing, `past_due` while past due, else `active`). A reason is
-- required, and an organization that already has the target status is refused. The change is made by T01's
-- careeros_set_org_plan (which writes its own org.status_changed row for the organization's trail); this function adds
-- exactly one `admin.org_status_set` row.
CREATE OR REPLACE FUNCTION public.careeros_admin_set_org_status(
	p_actor text, p_org_id text, p_status text, p_reason text
) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	org public.organization%ROWTYPE;
	sub_status text;
	target text;
	why text;
BEGIN
	PERFORM public.careeros_assert_platform_admin(p_actor);
	why := public.careeros_admin_check_reason(p_reason);
	IF p_status IS NULL OR p_status NOT IN ('suspended', 'active') THEN
		RAISE EXCEPTION 'careeros_admin: status must be suspended or active';
	END IF;
	SELECT * INTO org FROM public.organization WHERE id = p_org_id FOR UPDATE;
	IF NOT FOUND THEN
		RAISE EXCEPTION 'careeros_admin: unknown organization';
	END IF;
	IF p_status = 'suspended' THEN
		target := 'suspended';
	ELSE
		SELECT status INTO sub_status FROM public.subscription WHERE organization_id = p_org_id;
		target := CASE sub_status WHEN 'trialing' THEN 'trial' WHEN 'past_due' THEN 'past_due' ELSE 'active' END;
	END IF;
	IF org.status = target THEN
		RAISE EXCEPTION 'careeros_admin: the organization already has the status %', target;
	END IF;
	PERFORM public.careeros_set_org_plan(p_org_id, NULL, target, p_actor, why);
	INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, target_id, metadata)
	VALUES (p_org_id, p_actor, 'admin.org_status_set', 'organization', p_org_id,
		jsonb_build_object('from', org.status, 'to', target, 'reason', why));
	RETURN target;
END
$$;--> statement-breakpoint
-- 6. careeros_admin_set_org_plan: assigns a plan and, when given, the seat count stored on the subscription (it applies
-- once the subscription is live; see effectiveSeatLimit). Wraps careeros_set_org_plan (T01, which writes org.plan_changed)
-- and careeros_set_subscription (T01, subscription.updated); this function adds exactly one `admin.org_plan_set` row.
-- Seats must be at least 1 and within the plan's seat limit.
CREATE OR REPLACE FUNCTION public.careeros_admin_set_org_plan(
	p_actor text, p_org_id text, p_plan_id text, p_seats integer, p_reason text
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	org public.organization%ROWTYPE;
	pl public.plan%ROWTYPE;
	why text;
BEGIN
	PERFORM public.careeros_assert_platform_admin(p_actor);
	why := public.careeros_admin_check_reason(p_reason);
	SELECT * INTO org FROM public.organization WHERE id = p_org_id FOR UPDATE;
	IF NOT FOUND THEN
		RAISE EXCEPTION 'careeros_admin: unknown organization';
	END IF;
	SELECT * INTO pl FROM public.plan WHERE id = p_plan_id;
	IF NOT FOUND THEN
		RAISE EXCEPTION 'careeros_admin: unknown plan';
	END IF;
	IF p_seats IS NOT NULL AND (p_seats < 1 OR (pl.seat_limit IS NOT NULL AND p_seats > pl.seat_limit)) THEN
		RAISE EXCEPTION 'careeros_admin: seats must be at least 1 and within the plan''s seat limit';
	END IF;
	PERFORM public.careeros_set_org_plan(p_org_id, p_plan_id, NULL, p_actor, why);
	IF p_seats IS NOT NULL THEN
		PERFORM public.careeros_set_subscription(p_org_id, jsonb_build_object('seats', p_seats), p_actor, 'admin');
	END IF;
	INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, target_id, metadata)
	VALUES (p_org_id, p_actor, 'admin.org_plan_set', 'organization', p_org_id,
		jsonb_build_object('from', org.plan_id, 'to', p_plan_id, 'seats', p_seats, 'reason', why));
END
$$;--> statement-breakpoint
-- 7. careeros_admin_set_ai_overage (phase plan D5): lets an organization go past its AI credits, or stops it.
CREATE OR REPLACE FUNCTION public.careeros_admin_set_ai_overage(
	p_actor text, p_org_id text, p_allowed boolean, p_reason text
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	was boolean;
	why text;
BEGIN
	PERFORM public.careeros_assert_platform_admin(p_actor);
	why := public.careeros_admin_check_reason(p_reason);
	IF p_allowed IS NULL THEN
		RAISE EXCEPTION 'careeros_admin: allowed must be true or false';
	END IF;
	SELECT ai_overage_allowed INTO was FROM public.subscription WHERE organization_id = p_org_id FOR UPDATE;
	IF NOT FOUND THEN
		RAISE EXCEPTION 'careeros_admin: unknown organization';
	END IF;
	PERFORM public.careeros_set_subscription(p_org_id, jsonb_build_object('ai_overage_allowed', p_allowed), p_actor, 'admin');
	INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, target_id, metadata)
	VALUES (p_org_id, p_actor, 'admin.ai_overage_set', 'organization', p_org_id,
		jsonb_build_object('from', was, 'to', p_allowed, 'reason', why));
END
$$;--> statement-breakpoint
-- 8. careeros_admin_record_manual_payment: the platform admin's way to T04's careeros_record_manual_payment (an
-- institution paying by invoice). It adds the two-factor check T04's function does not make and returns T04's answer
-- (true when applied, false for a reference recorded before). T04's function writes the audit rows (billing.manual_payment
-- with the reference, amount and currency, plus the plan and subscription rows it causes), so this wrapper writes none.
CREATE OR REPLACE FUNCTION public.careeros_admin_record_manual_payment(
	p_actor text, p_org_id text, p_plan_id text, p_seats integer, p_interval text, p_period_start timestamptz,
	p_period_end timestamptz, p_amount bigint, p_currency text, p_reference text
) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
BEGIN
	PERFORM public.careeros_assert_platform_admin(p_actor);
	RETURN public.careeros_record_manual_payment(
		p_org_id, p_plan_id, p_seats, p_interval, p_period_start, p_period_end, p_amount, p_currency, p_reference, p_actor);
END
$$;--> statement-breakpoint
-- 9. careeros_admin_metrics: the business at a glance for [p_from, p_to) (default: the last 30 days) as one JSON
-- document. Organization counts by status and plan, new organizations, active members (people with a recent login who
-- belong to an organization), MRR and revenue in the period by currency (minor units: USD cents, KES cents), AI cost in
-- USD micros and, for the 50 organizations that cost most, that cost next to their revenue. MRR is the list price of
-- every active, paying (provider other than none) subscription in the currency of its latest recorded payment (USD
-- when none): it is an estimate for a negotiated plan. Revenue comes from the payment rows of audit_log
-- (billing.checkout_completed, billing.payment_succeeded, billing.manual_payment). Writes one platform audit row,
-- `admin.metrics_viewed`, with no detail.
CREATE OR REPLACE FUNCTION public.careeros_admin_metrics(p_actor text, p_from timestamptz, p_to timestamptz) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	v_to timestamptz := coalesce(p_to, now());
	v_from timestamptz := coalesce(p_from, coalesce(p_to, now()) - interval '30 days');
BEGIN
	PERFORM public.careeros_assert_platform_admin(p_actor);
	IF v_to <= v_from THEN
		RAISE EXCEPTION 'careeros_admin: the period must end after it starts';
	END IF;
	INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, metadata)
	VALUES (NULL, p_actor, 'admin.metrics_viewed', 'platform', '{}'::jsonb);
	RETURN jsonb_build_object(
		'from', v_from,
		'to', v_to,
		'orgsByStatus', coalesce((SELECT jsonb_object_agg(x.status, x.n) FROM
			(SELECT status, count(*) AS n FROM public.organization GROUP BY status) x), '{}'::jsonb),
		'orgsByPlan', coalesce((SELECT jsonb_object_agg(x.plan_id, x.n) FROM
			(SELECT plan_id, count(*) AS n FROM public.organization GROUP BY plan_id) x), '{}'::jsonb),
		'newOrgs', (SELECT count(*) FROM public.organization WHERE created_at >= v_from AND created_at < v_to),
		'activeMembers', (SELECT count(DISTINCT m.user_id) FROM public.member m JOIN public."user" u ON u.id = m.user_id
			WHERE u.last_active_at >= v_from AND u.last_active_at < v_to),
		'mrr', coalesce((SELECT jsonb_agg(jsonb_build_object('currency', y.currency, 'amountMinor', y.amount) ORDER BY y.currency)
			FROM (
				SELECT c.currency, round(sum(coalesce(
					CASE c.currency
						WHEN 'USD' THEN CASE s.billing_interval WHEN 'year' THEN pl.price_annual_usd_cents / 12.0 ELSE pl.price_monthly_usd_cents END
						WHEN 'KES' THEN CASE s.billing_interval WHEN 'year' THEN pl.price_annual_kes * 100 / 12.0 ELSE pl.price_monthly_kes * 100 END
					END, 0) * CASE WHEN pl.pricing_model = 'per_seat' THEN s.seats ELSE 1 END))::bigint AS amount
				FROM public.subscription s
				JOIN public.plan pl ON pl.id = s.plan_id
				JOIN public.organization o ON o.id = s.organization_id
				CROSS JOIN LATERAL (SELECT coalesce((
					SELECT a.metadata ->> 'currency' FROM public.audit_log a
					WHERE a.organization_id = s.organization_id
						AND a.action IN ('billing.checkout_completed', 'billing.payment_succeeded', 'billing.manual_payment')
						AND a.metadata ->> 'currency' ~ '^[A-Z]{3}$'
					ORDER BY a.id DESC LIMIT 1), 'USD') AS currency) c
				WHERE s.status = 'active' AND s.provider <> 'none' AND o.status <> 'suspended'
				GROUP BY c.currency) y), '[]'::jsonb),
		'revenue', coalesce((SELECT jsonb_agg(jsonb_build_object('currency', r.currency, 'amountMinor', r.amount) ORDER BY r.currency)
			FROM (SELECT a.metadata ->> 'currency' AS currency, sum((a.metadata ->> 'amount')::bigint) AS amount
				FROM public.audit_log a
				WHERE a.action IN ('billing.checkout_completed', 'billing.payment_succeeded', 'billing.manual_payment')
					AND a.created_at >= v_from AND a.created_at < v_to
					AND a.metadata ->> 'currency' ~ '^[A-Z]{3}$' AND a.metadata ->> 'amount' ~ '^[0-9]{1,15}$'
				GROUP BY 1) r), '[]'::jsonb),
		'aiCostUsdMicros', coalesce((SELECT sum(cost_usd_micros) FROM public.ai_usage
			WHERE source = 'platform' AND created_at >= v_from AND created_at < v_to), 0),
		'aiCostByOrg', coalesce((SELECT jsonb_agg(jsonb_build_object(
				'organizationId', t.organization_id, 'name', t.name, 'costUsdMicros', t.cost, 'credits', t.credits,
				'revenue', t.revenue) ORDER BY t.cost DESC, t.organization_id)
			FROM (
				SELECT u.organization_id, o.name, sum(u.cost_usd_micros) AS cost, sum(u.credits) AS credits,
					coalesce((SELECT jsonb_agg(jsonb_build_object('currency', q.currency, 'amountMinor', q.amount) ORDER BY q.currency)
						FROM (SELECT a.metadata ->> 'currency' AS currency, sum((a.metadata ->> 'amount')::bigint) AS amount
							FROM public.audit_log a
							WHERE a.organization_id = u.organization_id
								AND a.action IN ('billing.checkout_completed', 'billing.payment_succeeded', 'billing.manual_payment')
								AND a.created_at >= v_from AND a.created_at < v_to
								AND a.metadata ->> 'currency' ~ '^[A-Z]{3}$' AND a.metadata ->> 'amount' ~ '^[0-9]{1,15}$'
							GROUP BY 1) q), '[]'::jsonb) AS revenue
				FROM public.ai_usage u JOIN public.organization o ON o.id = u.organization_id
				WHERE u.source = 'platform' AND u.created_at >= v_from AND u.created_at < v_to
				GROUP BY u.organization_id, o.name
				ORDER BY sum(u.cost_usd_micros) DESC, u.organization_id LIMIT 50) t), '[]'::jsonb)
	);
END
$$;--> statement-breakpoint
-- 10. careeros_admin_list_audit: the audit log of every organization (and the platform's own rows), newest first, with
-- keyset paging on the time-sortable id (p_before = the id of the last row of the previous page). Filters: an
-- organization id, `p_platform_only` (rows with no organization), an exact action, a time range. Writes one platform
-- audit row, `admin.audit_viewed`, with no detail, AFTER reading, so a call does not list its own row.
CREATE OR REPLACE FUNCTION public.careeros_admin_list_audit(
	p_actor text, p_org_id text, p_platform_only boolean, p_action text, p_from timestamptz, p_to timestamptz,
	p_before text, p_limit integer
) RETURNS TABLE (
	entry_id text, organization_id text, organization_name text, actor_user_id text, impersonator_user_id text,
	action text, target_type text, target_id text, metadata jsonb, created_at timestamptz
)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
#variable_conflict use_column
DECLARE
	lim integer := least(greatest(coalesce(p_limit, 50), 1), 200);
BEGIN
	PERFORM public.careeros_assert_platform_admin(p_actor);
	RETURN QUERY
	SELECT a.id, a.organization_id, o.name, a.actor_user_id, a.impersonator_user_id, a.action, a.target_type, a.target_id,
		a.metadata, a.created_at
	FROM public.audit_log a LEFT JOIN public.organization o ON o.id = a.organization_id
	WHERE (p_org_id IS NULL OR a.organization_id = p_org_id)
		AND (NOT coalesce(p_platform_only, false) OR a.organization_id IS NULL)
		AND (p_action IS NULL OR a.action = p_action)
		AND (p_from IS NULL OR a.created_at >= p_from)
		AND (p_to IS NULL OR a.created_at < p_to)
		AND (p_before IS NULL OR a.id < p_before)
	ORDER BY a.id DESC LIMIT lim;
	INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, metadata)
	VALUES (NULL, p_actor, 'admin.audit_viewed', 'platform', '{}'::jsonb);
END
$$;--> statement-breakpoint
-- 11. Announcements (requirement 4). Written only through these functions, by platform admins, with audit.
-- careeros_admin_announcement_save creates one (p_id null) or updates one. Title 1 to 120 and body 1 to 1,000 characters
-- of plain text (the table's CHECKs), severity info or warning, ends after it starts. The optional plan and organization
-- narrow the audience. Writes `admin.announcement_saved` (for the organization when one is named).
CREATE OR REPLACE FUNCTION public.careeros_admin_announcement_save(
	p_actor text, p_id text, p_title text, p_body text, p_severity text, p_starts_at timestamptz, p_ends_at timestamptz,
	p_plan_id text, p_org_id text
) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	saved_id text;
BEGIN
	PERFORM public.careeros_assert_platform_admin(p_actor);
	IF p_org_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.organization WHERE id = p_org_id) THEN
		RAISE EXCEPTION 'careeros_admin: unknown organization';
	END IF;
	IF p_plan_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.plan WHERE id = p_plan_id) THEN
		RAISE EXCEPTION 'careeros_admin: unknown plan';
	END IF;
	IF p_id IS NULL THEN
		INSERT INTO public.announcement (title, body, severity, starts_at, ends_at, plan_id, organization_id, created_by)
		VALUES (btrim(p_title), btrim(p_body), p_severity, p_starts_at, p_ends_at, p_plan_id, p_org_id, p_actor)
		RETURNING id INTO saved_id;
	ELSE
		UPDATE public.announcement SET title = btrim(p_title), body = btrim(p_body), severity = p_severity,
			starts_at = p_starts_at, ends_at = p_ends_at, plan_id = p_plan_id, organization_id = p_org_id, updated_at = now()
		WHERE id = p_id RETURNING id INTO saved_id;
		IF saved_id IS NULL THEN
			RAISE EXCEPTION 'careeros_admin: unknown announcement';
		END IF;
	END IF;
	INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, target_id, metadata)
	VALUES (p_org_id, p_actor, 'admin.announcement_saved', 'announcement', saved_id,
		jsonb_build_object('created', p_id IS NULL, 'severity', p_severity, 'planId', p_plan_id));
	RETURN saved_id;
END
$$;--> statement-breakpoint
-- careeros_admin_announcement_list: the 200 most recent announcements. Writes `admin.announcements_listed`, no detail.
CREATE OR REPLACE FUNCTION public.careeros_admin_announcement_list(p_actor text) RETURNS SETOF public.announcement
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
BEGIN
	PERFORM public.careeros_assert_platform_admin(p_actor);
	INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, metadata)
	VALUES (NULL, p_actor, 'admin.announcements_listed', 'announcement', '{}'::jsonb);
	RETURN QUERY SELECT * FROM public.announcement ORDER BY created_at DESC, id DESC LIMIT 200;
END
$$;--> statement-breakpoint
-- careeros_admin_announcement_end: ends a running announcement now. Writes `admin.announcement_ended`.
CREATE OR REPLACE FUNCTION public.careeros_admin_announcement_end(p_actor text, p_id text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	row_ public.announcement%ROWTYPE;
BEGIN
	PERFORM public.careeros_assert_platform_admin(p_actor);
	SELECT * INTO row_ FROM public.announcement WHERE id = p_id FOR UPDATE;
	IF NOT FOUND THEN
		RAISE EXCEPTION 'careeros_admin: unknown announcement';
	END IF;
	IF row_.ends_at <= now() OR row_.starts_at >= now() THEN
		RAISE EXCEPTION 'careeros_admin: only a running announcement can be ended now; change the dates of any other';
	END IF;
	UPDATE public.announcement SET ends_at = now(), updated_at = now() WHERE id = p_id;
	INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, target_id, metadata)
	VALUES (row_.organization_id, p_actor, 'admin.announcement_ended', 'announcement', p_id, '{}'::jsonb);
END
$$;--> statement-breakpoint
-- The member side. These two are NOT admin functions: a member sees the announcements that apply to the organization
-- they are acting in, and dismisses one for themselves. The server passes the signed-in user and the organization it
-- resolved; the function still returns nothing unless the user is a member of that organization. No audit row (a member
-- reading a banner is not a cross-organization action).
CREATE OR REPLACE FUNCTION public.careeros_announcements_for_member(p_user_id text, p_org_id text)
RETURNS TABLE (id text, title text, body text, severity text, starts_at timestamptz, ends_at timestamptz)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
	SELECT a.id, a.title, a.body, a.severity, a.starts_at, a.ends_at
	FROM public.announcement a
	JOIN public.organization o ON o.id = p_org_id
	WHERE EXISTS (SELECT 1 FROM public.member m WHERE m.organization_id = p_org_id AND m.user_id = p_user_id)
		AND a.starts_at <= now() AND a.ends_at > now()
		AND (a.plan_id IS NULL OR a.plan_id = o.plan_id)
		AND (a.organization_id IS NULL OR a.organization_id = p_org_id)
		AND NOT EXISTS (SELECT 1 FROM public.announcement_dismissal d WHERE d.announcement_id = a.id AND d.user_id = p_user_id)
	ORDER BY a.starts_at DESC, a.id DESC LIMIT 5
$$;--> statement-breakpoint
CREATE OR REPLACE FUNCTION public.careeros_announcement_dismiss(p_user_id text, p_announcement_id text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	fresh boolean;
BEGIN
	IF NOT EXISTS (SELECT 1 FROM public."user" WHERE id = p_user_id) OR NOT EXISTS (SELECT 1 FROM public.announcement WHERE id = p_announcement_id) THEN
		RETURN false;
	END IF;
	INSERT INTO public.announcement_dismissal (announcement_id, user_id) VALUES (p_announcement_id, p_user_id)
	ON CONFLICT DO NOTHING RETURNING true INTO fresh;
	RETURN coalesce(fresh, false);
END
$$;--> statement-breakpoint
-- 12. Impersonation (requirement 3, phase plan D6). The server passes the SHA-256 of a one-time token it generated and
-- the origin of the member's organization host; the token reaches that host in a URL fragment and is redeemed there
-- (the P2-T05 pattern). A support session lasts 60 minutes from the START, fixed here and never extended.
--
-- careeros_admin_impersonation_start: the actor must be a platform admin; the target must exist, not be banned, not be a
-- platform admin (any admin, with or without two-factor: an admin cannot be impersonated) and be a member of the
-- organization; a reason of 3 to 500 characters is required. Writes TWO audit rows in one transaction: `impersonation.started`
-- in the member's organization and `admin.impersonation_started` in the platform log.
CREATE OR REPLACE FUNCTION public.careeros_admin_impersonation_start(
	p_actor text, p_target_user_id text, p_org_id text, p_reason text, p_target_origin text, p_token_hash text
) RETURNS TABLE (out_id text, out_expires_at timestamptz, out_token_expires_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	target public."user"%ROWTYPE;
	why text;
	new_id text;
	ends timestamptz := now() + interval '60 minutes';
	token_ends timestamptz := now() + interval '60 seconds';
BEGIN
	PERFORM public.careeros_assert_platform_admin(p_actor);
	why := public.careeros_admin_check_reason(p_reason);
	IF p_token_hash IS NULL OR p_token_hash !~ '^[0-9a-f]{64}$' THEN
		RAISE EXCEPTION 'careeros_admin: invalid token';
	END IF;
	IF p_target_origin IS NULL OR p_target_origin !~ '^https?://[a-z0-9.-]{1,253}(:[0-9]{1,5})?$' THEN
		RAISE EXCEPTION 'careeros_admin: invalid target origin';
	END IF;
	SELECT * INTO target FROM public."user" WHERE id = p_target_user_id;
	IF NOT FOUND THEN
		RAISE EXCEPTION 'careeros_admin: unknown user';
	END IF;
	IF 'admin' = ANY (string_to_array(replace(coalesce(target.role, ''), ' ', ''), ',')) THEN
		RAISE EXCEPTION 'careeros_admin: a platform admin cannot be impersonated' USING ERRCODE = '42501';
	END IF;
	IF coalesce(target.banned, false) AND (target.ban_expires IS NULL OR target.ban_expires > now()) THEN
		RAISE EXCEPTION 'careeros_admin: the user is banned';
	END IF;
	IF NOT EXISTS (SELECT 1 FROM public.member WHERE organization_id = p_org_id AND user_id = p_target_user_id) THEN
		RAISE EXCEPTION 'careeros_admin: the user is not a member of the organization';
	END IF;
	INSERT INTO public.impersonation (impersonator_user_id, target_user_id, organization_id, reason, target_origin, token_hash,
		token_expires_at, expires_at)
	VALUES (p_actor, p_target_user_id, p_org_id, why, p_target_origin, p_token_hash, token_ends, ends)
	RETURNING id INTO new_id;
	INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, target_id, metadata)
	VALUES (p_org_id, p_actor, 'impersonation.started', 'user', p_target_user_id,
		jsonb_build_object('impersonationId', new_id, 'reason', why, 'expiresAt', ends));
	INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, target_id, metadata)
	VALUES (NULL, p_actor, 'admin.impersonation_started', 'user', p_target_user_id,
		jsonb_build_object('impersonationId', new_id, 'organizationId', p_org_id, 'reason', why, 'expiresAt', ends));
	RETURN QUERY SELECT new_id, ends, token_ends;
END
$$;--> statement-breakpoint
-- careeros_impersonation_redeem: on the member's organization host, in one statement: the token is live (database
-- clock), unredeemed, not ended, and its hash, the host's origin and the host's organization all match; the actor is still
-- a platform admin and the target still an allowed member. Zero rows is one answer for every reason.
CREATE OR REPLACE FUNCTION public.careeros_impersonation_redeem(
	p_id text, p_token_hash text, p_target_origin text, p_org_id text
) RETURNS TABLE (out_target_user_id text, out_organization_id text, out_impersonator_user_id text, out_expires_at timestamptz)
LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
	UPDATE public.impersonation i SET redeemed_at = now()
	WHERE i.id = p_id AND i.redeemed_at IS NULL AND i.ended_at IS NULL
		AND i.token_hash = p_token_hash AND i.token_expires_at > now() AND i.expires_at > now()
		AND i.target_origin = p_target_origin AND i.organization_id = p_org_id
		AND public.careeros_is_platform_admin(i.impersonator_user_id)
		AND EXISTS (SELECT 1 FROM public.member m WHERE m.organization_id = i.organization_id AND m.user_id = i.target_user_id)
		AND EXISTS (SELECT 1 FROM public."user" u WHERE u.id = i.target_user_id
			AND NOT ('admin' = ANY (string_to_array(replace(coalesce(u.role, ''), ' ', ''), ',')))
			AND (NOT coalesce(u.banned, false) OR (u.ban_expires IS NOT NULL AND u.ban_expires <= now())))
	RETURNING i.target_user_id, i.organization_id, i.impersonator_user_id, i.expires_at
$$;--> statement-breakpoint
-- careeros_impersonation_attach_session: records which Better Auth session the redeem step created, once.
CREATE OR REPLACE FUNCTION public.careeros_impersonation_attach_session(
	p_id text, p_session_id text, p_target_user_id text
) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	done boolean;
BEGIN
	UPDATE public.impersonation SET session_id = p_session_id
	WHERE id = p_id AND target_user_id = p_target_user_id AND session_id IS NULL AND redeemed_at IS NOT NULL AND ended_at IS NULL
	RETURNING true INTO done;
	RETURN coalesce(done, false);
END
$$;--> statement-breakpoint
-- careeros_impersonation_active: whether this session of this member, impersonated by this admin, is a live support
-- session (attached, not ended, not past its 60 minutes) and the admin may still impersonate. The server asks on every
-- request of an impersonated session; a session without such a row is refused.
CREATE OR REPLACE FUNCTION public.careeros_impersonation_active(
	p_session_id text, p_user_id text, p_impersonator_user_id text
) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
	SELECT EXISTS (
		SELECT 1 FROM public.impersonation i
		WHERE i.session_id = p_session_id AND i.target_user_id = p_user_id AND i.impersonator_user_id = p_impersonator_user_id
			AND i.ended_at IS NULL AND i.expires_at > now() AND public.careeros_is_platform_admin(i.impersonator_user_id)
	)
$$;--> statement-breakpoint
-- careeros_impersonation_for_session: what the banner shows, for the member's own session only.
CREATE OR REPLACE FUNCTION public.careeros_impersonation_for_session(p_session_id text, p_user_id text)
RETURNS TABLE (out_id text, out_organization_id text, out_organization_name text, out_user_name text, out_expires_at timestamptz)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
	SELECT i.id, i.organization_id, o.name, u.name, i.expires_at
	FROM public.impersonation i
	JOIN public."user" u ON u.id = i.target_user_id
	LEFT JOIN public.organization o ON o.id = i.organization_id
	WHERE i.session_id = p_session_id AND i.target_user_id = p_user_id AND i.ended_at IS NULL AND i.expires_at > now()
$$;--> statement-breakpoint
-- careeros_impersonation_end: the member side of "End now". Ends the live support session of this session and user (false
-- when there is none) and writes TWO audit rows: `impersonation.ended` in the member's organization and
-- `admin.impersonation_ended` in the platform log.
CREATE OR REPLACE FUNCTION public.careeros_impersonation_end(p_session_id text, p_user_id text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	row_ public.impersonation%ROWTYPE;
BEGIN
	UPDATE public.impersonation SET ended_at = now(), end_reason = 'ended'
	WHERE session_id = p_session_id AND target_user_id = p_user_id AND ended_at IS NULL
	RETURNING * INTO row_;
	IF NOT FOUND THEN
		RETURN false;
	END IF;
	INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, target_id, metadata)
	VALUES (row_.organization_id, row_.impersonator_user_id, 'impersonation.ended', 'user', row_.target_user_id,
		jsonb_build_object('impersonationId', row_.id, 'endReason', 'ended', 'startedAt', row_.started_at));
	INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, target_id, metadata)
	VALUES (NULL, row_.impersonator_user_id, 'admin.impersonation_ended', 'user', row_.target_user_id,
		jsonb_build_object('impersonationId', row_.id, 'organizationId', row_.organization_id, 'endReason', 'ended'));
	RETURN true;
END
$$;--> statement-breakpoint
-- careeros_impersonation_expire_due: the scheduled sweep. Ends every support session whose 60 minutes are over (or whose
-- link was never used) that nobody ended, with the same two audit rows as an explicit end, `endReason` expired. Returns
-- how many it ended. Safe to run on several instances at once (each row is ended once).
CREATE OR REPLACE FUNCTION public.careeros_impersonation_expire_due() RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	row_ public.impersonation%ROWTYPE;
	ended integer := 0;
BEGIN
	FOR row_ IN
		UPDATE public.impersonation SET ended_at = now(), end_reason = 'expired'
		WHERE ended_at IS NULL AND expires_at <= now()
		RETURNING *
	LOOP
		INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, target_id, metadata)
		VALUES (row_.organization_id, row_.impersonator_user_id, 'impersonation.ended', 'user', row_.target_user_id,
			jsonb_build_object('impersonationId', row_.id, 'endReason', 'expired', 'startedAt', row_.started_at,
				'usedSession', row_.session_id IS NOT NULL));
		INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, target_id, metadata)
		VALUES (NULL, row_.impersonator_user_id, 'admin.impersonation_ended', 'user', row_.target_user_id,
			jsonb_build_object('impersonationId', row_.id, 'organizationId', row_.organization_id, 'endReason', 'expired'));
		ended := ended + 1;
	END LOOP;
	RETURN ended;
END
$$;--> statement-breakpoint
-- 13. Grants: every function is revoked from PUBLIC and executable by the app role only (the bootstrap script repeats the
-- grants for databases that migrated before the role existed).
DO $$ BEGIN
	REVOKE ALL ON FUNCTION public.careeros_is_platform_admin(text) FROM PUBLIC;
	REVOKE ALL ON FUNCTION public.careeros_assert_platform_admin(text) FROM PUBLIC;
	REVOKE ALL ON FUNCTION public.careeros_admin_check_reason(text) FROM PUBLIC;
